script:
frappe.ui.form.on('Task', {
    onload: function(frm) {
        frappe.db.get_list('ToDo', {
            filters: {
                'reference_type': 'Project',
                'allocated_to': frappe.session.user,
                'status': 'Open'
            },
            fields: ['reference_name']
        }).then(records => {
            let assigned_projects = records.map(row => row.reference_name);

            if (assigned_projects.length === 0) {
                assigned_projects = ["No Assigned Projects Found"];
            }

            frm.set_query('project', function() {
                return {
                    filters: [
                        ['Project', 'name', 'in', assigned_projects]
                    ]
                };
            });
        });
    }
});

frappe.ui.form.on("Project", {
    refresh: function(frm) {

        $(".form-assignments").hide();

        if (
            frappe.user_roles.includes("Projects Manager") ||
            frappe.user === "Administrator"
        ) {
            frm.set_df_property(
                "custom_assign_project_user",
                "hidden",
                0
            );
        } else {
            frm.set_df_property(
                "custom_assign_project_user",
                "hidden",
                1
            );

            if (
                frm.is_new() &&
                frappe.user_roles.includes("Projects User") &&
                !frm.doc.custom_assign_project_user
            ) {
                frm.set_value(
                    "custom_assign_project_user",
                    frappe.session.user
                );
            }
        }

        frm.set_query(
            "custom_assign_project_user",
            function() {
                return {
                    query: "frappe.core.doctype.user.user.user_query",
                    filters: {
                        enabled: 1,
                        user_type: "System User",
                        role: "Projects User"
                    }
                };
            }
        );
    },

    after_save: function(frm) {

        if (frm.doc.custom_assign_project_user) {

            frappe.call({
                method: "frappe.desk.form.assign_to.add",

                args: {
                    doctype: frm.doc.doctype,
                    name: frm.doc.name,
                    assign_to: [
                        frm.doc.custom_assign_project_user
                    ],
                    description: __(
                        "Project assigned via Manager form selector."
                    ),
                    priority: "Medium"
                },

                callback: function(r) {

                    if (!r.exc) {

                        frappe.show_alert({
                            message: __(
                                "Successfully assigned to {0}",
                                [
                                    frm.doc.custom_assign_project_user
                                ]
                            ),
                            indicator: "green"
                        });

                    }

                }
            });
        }
    }
});
